export const scenarioBodies: Record<string, string> = {
  "contract-formation": "算。合同是双方意思表示一致的协议，并不要求必须写成书面文件。口头说好的事，也可能成立合同。 法律、行政法规规定或者当事人约定必须书面的，才必须采用书面形式。日常租房通常不强制书面，但写下来能避免很多争议。 如果有聊天记录、转账记录、录音等能证明双方约定的材料，可以先和对方协商；协商不成，再考虑走法律途径。 重要的事尽量留下书面记录：合同、聊天记录、转账备注、收据都可以。口头约定不是无效，难的是证明。 想进一步了解概念，可以看 合同成立 和 合同的形式 。",
  "contract-breach": "如果合同约定了他应当在某个时间开工，拖了两个月没动，属于履行不符合约定，或者迟延履行。 可以要求继续履行、采取补救措施或者赔偿损失。如果拖到合同目的无法实现，或者催告后仍不履行，可以解除合同。 先把合同、付款记录、催工聊天记录整理好，书面催告对方在合理期限内履行；仍不履行的，再考虑解除合同并要求退款、赔偿。 先催告、再解除，顺序很重要。直接说「我不干了」可能被对方反过来主张你违约。 相关概念： 违约责任 、 合同解除 。",
  "contract-deposit": "「定金」是法律规定的担保方式，适用定金罚则。「订金」通常只是预付款，法律上没有定金罚则，能不能退主要看合同约定和双方协商。 付定金的一方不履行债务，致使不能实现合同目的的，无权要求返还定金；收定金的一方不履行，应当双倍返还定金。 先看收据、合同上写的是哪个字，再看有没有约定退款条件。写的是「订金」，可以主张按预付款处理；写的是「定金」，单方不买通常要不回来。 签合同、开收据时把字写清楚。口头说「订金」但收据写「定金」，争议时以书面为准。定金数额也有限制，不能超过主合同标的额的一定比例。 相关概念： 定金罚则 、 违约金 。",
  "contract-online": "电商经营者发布的商品信息符合要约条件的，你选择商品并提交订单成功，合同通常就成立，除非双方另有约定。 快递物流交付的，收货人签收时间一般为交付时间。签收前后的风险承担可能不同。 网络购物通常有七日无理由退货等规则，具体规定主要在《消费者权益保护法》，本库暂未收录。先看平台规则、商品是否属于例外情形，再决定怎么申请。 拆封试听不一定等于不能退，但商品完好的举证责任往往在你这边。保留包装、配件、聊天记录和物流信息。 相关概念： 电子合同与网购 、 合同的形式 。",
  "contract-lease": "押金不是法律明文规定的担保方式，性质和退还条件主要看合同约定。它和「定金」不是一回事，不适用定金罚则。 租期届满，承租人应当返还租赁物，返还的租赁物应当符合按照约定或者根据租赁物性质使用后的状态。正常使用留下的痕迹，不等于损坏。 要求房东说明损坏部位、维修费用和依据，保留入住和退房时的照片、视频、聊天记录。协商不成，可以走调解或诉讼。 入住时拍一套照片，退房时再拍一套，是押金纠纷里最便宜的证据。合同里最好写清扣押金的具体情形和上限。 相关概念： 押金 、 租赁合同 。",
  "contract-loan": "自然人之间的借款合同，自贷款人提供借款时成立。转账记录能证明你实际交付了钱，这很关键。 借款合同对支付利息没有约定的，视为没有利息。自然人之间对利息约定不明的，也视为没有利息。 一般诉讼时效是三年，从知道或者应当知道权利受损及义务人之日起算。催款、对方承诺还款等行为可能引起时效中断。 没有借条时，转账备注、聊天记录、通话录音、对方承认欠款的文字，都能补强证据。让对方在微信里确认「我欠你 3 万，某月某日前还」，比空口争论有用。 相关概念： 借款合同 、 诉讼时效 。",
  "contract-format-clause": "为了重复使用而预先拟定、订立合同时没有和你协商的条款，可能属于格式条款。 不合理地免除或者减轻商家责任、加重你的责任、限制你主要权利的格式条款，可能无效。 保留办卡时的合同、宣传页、聊天记录，要求商家说明扣费依据。协商不成，可以向市场监管部门投诉或走法律途径。 「最终解释权」不是法律赋予商家的特权。遇到明显不公平的格式条款，不要只因为对方写了就认。 相关概念： 格式条款 、 合同成立 。",
  "contract-guarantee": "保证人向债权人承诺，债务人不履行到期债务时，由保证人履行债务或者承担责任。 对保证方式没有约定或者约定不明确的，按照一般保证承担保证责任。一般保证人享有先诉抗辩权。 先看担保合同写的是哪种保证方式、担保范围多大。不要轻易再签还款承诺或新的担保文件。 担保不是「帮个忙签个字」这么简单。签字前看清保证方式、金额、期限和追偿条款。 相关概念： 保证合同 、 借款合同 。",
  "contract-gift": "赠与人把自己的财产无偿给予受赠人，受赠人表示接受，赠与合同成立。 在赠与财产的权利转移之前，赠与人一般可以撤销赠与。经过公证或者具有救灾、扶贫、助残等公益、道德义务性质的赠与除外。 如果受赠人严重侵害赠与人或者其近亲属的合法权益等，赠与人还可能依法撤销赠与。 大额赠与写清楚条件、交付时间和是否可撤销。公证赠与和公益赠与通常不能随意反悔。 相关概念： 赠与合同 。",
  "contract-agency": "代理人在代理权限内，以被代理人名义实施的行为，对被代理人发生效力。 没有代理权、超越代理权或者代理权终止后仍然实施代理行为，未经被代理人追认的，对被代理人不发生效力。 查看委托合同和授权范围，明确告诉买家中介没有这项权限。是否追认要谨慎，追认后可能就要承担后果。 给中介的授权尽量书面写清范围、期限和价格底线。口头「你看着办」容易变成越权争议。 相关概念： 委托代理 。",
  "contract-fraud": "一方以欺诈手段，使对方在违背真实意思的情况下实施的民事法律行为，受欺诈方有权请求法院或者仲裁机构撤销。 一般应当自知道或者应当知道撤销事由之日起一年内行使撤销权，重大误解为九十日。 保存宣传单、聊天记录、录音、合同和付款凭证。先与商家协商，协商不成及时咨询律师或向法院、仲裁机构主张。 「保本保收益」这类承诺如果没写进合同，事后很难证明。签字前把关键承诺写进书面条款。 相关概念： 欺诈与撤销 、 合同成立 。",
  "contract-sale": "买卖合同是出卖人转移标的物所有权、买受人支付价款的合同。二手交易也可以形成买卖合同。 出卖人应当履行交付标的物并转移所有权的义务。质量不符合约定的，可以主张违约责任。 保留商品页面、聊天记录、鉴定报告、物流和付款记录。先走平台售后，必要时再主张退货退款和赔偿。 二手交易尽量走平台担保支付，不要脱离平台私下转账。商品描述和聊天记录就是你的合同证据。 相关概念： 买卖合同 、 违约责任 。",
  "labor-probation": "试用期的长短受法律限制，同一单位与同一劳动者只能约定一次，试用期包含在劳动合同期限内。 以试用期不符合录用条件解除的，公司需要有明确的录用条件，并能证明你不符合。只是口头说「不合适」，不一定够。 要求公司出具书面解除通知和理由，保留岗位说明、考核记录、聊天记录。如果认为属于违法解除，可以主张赔偿金或申请劳动仲裁。 签劳动合同前看清试用期长度、工资和录用条件。入职后保留岗位职责、考核标准、工作成果记录。 相关概念： 试用期 、 违法解除赔偿金 。",
  "labor-written-contract": "建立劳动关系应当订立书面劳动合同。已建立劳动关系但没同时订立的，应当自用工之日起一个月内订立。 用工超过一个月不满一年未订立书面劳动合同的，用人单位应当每月支付二倍工资。 保留工资流水、考勤记录、工作群聊天、工牌、入职通知等能证明劳动关系的材料。双倍工资受仲裁时效限制，尽早主张。 不要因为「公司说以后再签」就一直等。保留书面或聊天形式的催签记录，能帮助你证明未签合同的责任不在你。 相关概念： 书面劳动合同 、 双倍工资 。",
  "labor-overtime": "延长工作时间一般要与工会和劳动者协商，每日一般不超过一小时；特殊原因下每日不超过三小时，每月不超过三十六小时。 工作日加班不低于 150%，休息日加班又不能补休的不低于 200%，法定节假日不低于 300%。 考勤记录、排班表、工作群通知、加班审批记录、打车报销记录都能用。与争议有关的考勤材料由单位掌握的，可以要求单位提供。 「工资已包含加班费」不是万能挡箭牌。要看工资结构、加班时长和当地规定。保留每月工资条和考勤记录，离职后很难补。 相关概念： 加班工资 、 工作时间 。",
  "labor-wrongful-dismissal": "合法解除、协商解除、违法解除，结果完全不同。要求公司出具书面解除通知，写清依据和日期。 按工作年限，每满一年一个月工资；六个月以上不满一年按一年算；不满六个月半个月工资。 用人单位违法解除或终止劳动合同的，按经济补偿标准的二倍支付赔偿金。 公司让你签「协商解除」或「个人原因离职」时，先看清谁提出、补偿多少。签字后再主张违法解除，难度会大很多。 相关概念： 违法解除赔偿金 、 经济补偿 。",
  "labor-work-injury": "职工应当参加工伤保险，由用人单位缴纳工伤保险费，职工个人不缴纳。 职工因工作原因受到事故伤害或者患职业病，经工伤认定的，享受工伤保险待遇；经劳动能力鉴定丧失劳动能力的，享受伤残待遇。 及时就医，保留病历、诊断证明、事故现场照片、同事证言。尽快向单位或社保部门了解工伤认定申请流程和期限。 工伤认定程序主要规定在《工伤保险条例》，本库暂未收录。单位不配合申请时，可以自行向社保行政部门咨询和申请。 相关概念： 工伤认定 、 社会保险 。",
  "labor-arbitration": "发生劳动争议，协商、调解不成，可以向劳动争议仲裁委员会申请仲裁；对仲裁裁决不服，再依法向法院起诉。 一般仲裁时效是一年，从知道或者应当知道权利被侵害之日起算。拖欠劳动报酬在劳动关系存续期间有特殊规则。 先证明劳动关系和基本事实：合同、工资流水、考勤、工作群记录。与争议有关、由单位掌握的证据，可以要求单位提供。 各地仲裁申请材料、管辖和流程略有差异。先打当地劳动仲裁咨询电话，或到政务服务中心窗口拿一份申请材料清单，比盲目跑一趟省时间。 相关概念： 劳动仲裁 、 仲裁时效 。",
  "labor-open-ended": "连续订立二次固定期限劳动合同，且劳动者没有法定情形，续订劳动合同时，除劳动者提出订立固定期限劳动合同外，应当订立无固定期限劳动合同。 无固定期限只是没有确定终止时间，在法定情形下仍然可以解除。 保留前两次劳动合同、续签通知和沟通记录。如果公司拒绝依法签订，可以咨询劳动仲裁机构。 续签时看清合同类型和期限。公司让你先签「自愿固定期限」的文件，要明白这意味着什么。 相关概念： 无固定期限劳动合同 、 书面劳动合同 。",
  "labor-noncompete": "竞业限制人员限于高级管理人员、高级技术人员和其他负有保密义务的人员。 对负有保密义务的劳动者，可以约定竞业限制条款，并约定在解除或者终止劳动合同后，在竞业限制期限内按月给予经济补偿。 查看协议里的限制范围、期限和补偿标准。公司长期不支付补偿的，劳动者可以依法主张相应权利。 竞业限制不是「离职后什么都不能干」。范围、地域、期限都要合理，且单位要支付补偿。 相关概念： 竞业限制 、 辞职与被迫解除 。",
  "labor-dispatch": "劳务派遣用工是补充形式，只能在临时性、辅助性或者替代性的工作岗位上实施。 劳务派遣单位是用人单位，应当履行用人单位对劳动者的义务。 保留劳动合同、工资条、考勤和岗位说明。如果长期在核心岗位使用派遣，可能涉及违法派遣，可以咨询劳动监察或仲裁。 「临时性、辅助性、替代性」是派遣岗位的边界。长期核心岗位大量使用派遣，值得警惕。 相关概念： 劳务派遣 、 书面劳动合同 。",
  "labor-pregnancy": "女职工在孕期、产期、哺乳期的，用人单位不得依照本法关于无过失性辞退和经济性裁员的规定解除劳动合同。 劳动合同期满，有前述三期等法定情形的，劳动合同应当续延至相应情形消失时终止。 保留怀孕证明、沟通记录、考勤和工资记录。不要轻易签「个人原因离职」。认为被违法辞退的，可以主张赔偿金或申请仲裁。 三期保护不是绝对的。严重违纪等法定情形仍可能被解除，但公司需要有充分依据和程序。 相关概念： 三期保护 、 违法解除赔偿金 。",
  "labor-resignation": "劳动者提前三十日以书面形式通知用人单位，可以解除劳动合同；试用期内提前三日通知。 公司未及时足额支付劳动报酬、未依法缴纳社保等，劳动者可以解除劳动合同并主张经济补偿。 用可留痕的方式提交辞职通知，保留送达记录。离职前整理工资、考勤、社保和交接材料。 「不批准」不等于劳动关系不能解除。关键是依法通知并保留证据；主动辞职一般没有经济补偿。 相关概念： 辞职与被迫解除 、 经济补偿 。",
  "labor-probation-pay": "劳动者在试用期的工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准。 如果合同约定工资的 80% 已经低于当地最低工资标准，那就不合法。 核对劳动合同约定的工资、工资条和当地最低工资标准。发现少发，可以先与公司沟通，必要时向劳动监察部门反映。 试用期不是「廉价期」。工资不得低于合同约定工资的 80%，也不得低于当地最低工资。 相关概念： 试用期 。",
  "marriage-property": "一方的婚前财产属于个人财产，不会因为结婚自动变成共同财产。 婚后用共同财产还贷的部分、房屋对应的增值，实践中通常需要给对方补偿，但具体计算规则由婚姻家庭编司法解释规定，本库暂未收录。 保留首付凭证、贷款合同、还款流水、房产登记信息。双方也可以书面约定财产归属，减少争议。 房产证写谁的名字、首付谁出、婚后谁还贷，是三个不同的问题。不要只看房产证，也不要只凭口头说法。 相关概念： 个人财产 、 夫妻共同财产 。",
  "marriage-betrothal-gift": "法律禁止借婚姻索取财物，但不是一律禁止彩礼。 要看是否办理结婚登记、是否共同生活、共同生活时间、彩礼数额和用途、双方过错等。具体规则由最高人民法院相关司法解释规定，本库暂未收录。 保留给付彩礼的转账记录、聊天记录、媒人证言、婚礼和共同生活的证据。先协商，协商不成再考虑调解或诉讼。 「没领证」「领证没共同生活」「给付导致生活困难」是实践中常被讨论的情形，但每个案件都要看具体事实，不能只套一句话。 相关概念： 彩礼 。",
  "marriage-fault": "重婚、与他人同居、实施家庭暴力、虐待遗弃家庭成员，以及有其他重大过错，导致离婚的，无过错方可以请求损害赔偿。 一般出轨不一定达到「与他人同居」。法律上的同居通常指持续、稳定地共同生活。只有暧昧聊天或偶发关系，未必能满足这一条件。 保留能证明持续共同生活的材料，如长期同住记录、邻居证言、稳定的共同生活痕迹。同时评估是否还有家暴、转移财产等其他法定情形。 不要为了取证闯入他人住宅、偷装监控或非法获取隐私信息。违法取得的证据可能不被采纳，还可能让你承担法律责任。 相关概念： 离婚损害赔偿 。",
  "marriage-custody": "不满两周岁的子女，以由母亲直接抚养为原则。已满两周岁、协议不成的，法院按最有利于未成年子女的原则判决。已满八周岁的，应当尊重孩子的真实意愿。 不直接抚养的一方应当负担部分或全部抚养费，多少和期限先由双方协议，协议不成由法院判决。 准备能说明谁长期照顾孩子、居住和教育环境、双方工作时间的材料。协议离婚时，把探望方式、抚养费支付方式写清楚。 不要把孩子藏起来、阻止对方探望来「争取抚养权」。这可能被认定为不利于孩子，也可能引发新的纠纷。 相关概念： 子女抚养 、 抚养费 。",
  "marriage-debt": "双方共同签名、一方事后追认，或者一方以个人名义为家庭日常生活需要所负的债务，一般属于共同债务。 一方以个人名义超出家庭日常生活需要所负的债务，原则上不属于共同债务，除非债权人能证明用于夫妻共同生活、共同生产经营或者基于双方共同意思表示。 离婚时，夫妻共同债务应当共同偿还。共同财产不足清偿的，由双方协议；协议不成，由法院判决。 不要轻易在对方的借条、还款承诺上签字，也不要用自己的账户帮对方走账。签字和转账都可能被用来证明你认可这笔债务。 相关概念： 夫妻共同债务 。",
  "marriage-domestic-violence": "家庭成员之间以殴打、捆绑、残害、限制人身自由以及经常性谩骂、恐吓等方式实施的身体、精神等侵害行为，可能构成家庭暴力。 情况紧急先报警、就医，联系妇联、居委会或信任的人。可以保存报警记录、验伤材料、照片、聊天记录和证人联系方式。 遭受家庭暴力或者面临现实危险，可以向法院申请人身安全保护令，不以离婚为前提。 因家庭暴力导致离婚，调解无效的，法院应当准予离婚。第一时间报警和就医，既是为了安全，也是后续维权的重要证据。 相关概念： 家庭暴力 、 人身安全保护令 。",
  "marriage-cohabitation": "无效或者被撤销的婚姻自始没有法律约束力，当事人不具有夫妻的权利和义务。 同居期间所得的财产，由当事人协议处理；协议不成的，由法院根据照顾无过错方的原则判决。 整理出资记录、转账凭证、房产登记、聊天记录。能证明各自出资比例的，按出资和约定主张更清晰。 同居期间大额共同支出，尽量保留转账备注和书面约定。不要默认「住在一起就是共同财产」。 相关概念： 同居财产 、 夫妻共同财产 。",
  "marriage-marital-agreement": "男女双方可以约定婚姻关系存续期间所得的财产以及婚前财产归各自所有、共同所有或者部分各自所有、部分共同所有。 约定应当采用书面形式，写清财产范围、归属、债务承担和生效时间。没有约定或者约定不明确的，适用法定财产规则。 双方自愿签署，保留原件。涉及房产、股权等重大财产时，建议咨询律师并办理相应登记或公证。 财产协议不要只写一句「各归各的」。哪些财产、哪些债务、怎么执行，越具体越不容易争议。 相关概念： 婚前财产约定 、 夫妻共同财产 。",
  "marriage-adoption": "收养人需要符合无子女或者只有一名子女、有抚养教育能力、无相关违法犯罪记录等法定条件。 收养应当向县级以上人民政府民政部门登记，收养关系自登记之日起成立。 先向当地民政部门咨询收养条件、材料和评估流程。不要仅凭私下协议就认为收养关系已经成立。 收养涉及未成年人权益，法律程序比较严格。任何「私下送养、给钱领养」都可能踩到法律红线。 相关概念： 收养 。",
  "marriage-elderly-support": "成年子女对父母负有赡养、扶助和保护的义务。 成年子女不履行赡养义务的，缺乏劳动能力或者生活困难的父母，有要求成年子女给付赡养费的权利。 先协商赡养方式和金额，考虑双方收入、医疗支出和照护需求。协商不成，可以由调解组织调解或向法院起诉。 赡养不只是给钱，还包括生活照料和精神慰藉。具体金额会结合父母需要和子女负担能力判断。 相关概念： 赡养义务 。",
  "marriage-stepchild": "继父或者继母和受其抚养教育的继子女间的权利义务，适用父母子女关系的规定。 法定继承中的子女包括有扶养关系的继子女。 收集共同生活、抚养教育、费用支出等证据。是否存在扶养关系，往往决定继子女能否作为法定继承人。 继父母子女关系不是结婚就自动形成。是否共同生活、是否实际抚养教育，是争议焦点。 相关概念： 继父母子女 、 继承基础 。",
  "marriage-hidden-assets": "离婚时隐藏、转移、变卖、毁损、挥霍夫妻共同财产，或者伪造共同债务企图侵占另一方财产的，分割时可以少分或者不分。 婚姻关系存续期间，一方有严重损害夫妻共同财产利益行为的，另一方可以向法院请求分割共同财产。 尽快保存银行流水、转账记录、车辆登记、聊天记录，必要时申请财产保全。发现越早，越容易固定证据。 离婚后发现对方转移财产的，还可以依法请求再次分割。重点是证据和时效，不要只靠口头争执。 相关概念： 隐藏转移共同财产 、 夫妻共同财产 。"
};

export const conceptBodies: Record<string, string> = {
  "contract-agency": "民事主体可以通过代理人实施民事法律行为。依照法律规定、当事人约定或者民事法律行为的性质，应当由本人亲自实施的，不得代理。 代理人在代理权限内，以被代理人名义实施的民事法律行为，对被代理人发生效力。 行为人没有代理权、超越代理权或者代理权终止后仍然实施代理行为，未经被代理人追认的，对被代理人不发生效力。 相关概念： 合同成立 。",
  "contract-breach": "一方不履行合同义务，或者履行得不符合约定，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。 如果是欠钱、欠租金这类金钱债务，对方可以直接要求支付。 具体赔多少，看 损失赔偿 ；什么情况下能解除，看 合同解除 。",
  "contract-damages": "损失赔偿额应当相当于因违约造成的损失，包括合同履行后本可以获得的利益。 但有一个重要限制：不得超过违约一方在订立合同时预见到或者应当预见到的因违约可能造成的损失。 如果合同里约定了违约金，处理方式会不同，见 违约金 。",
  "contract-deposit-money": "押金不是民法典明文规定的担保方式，它的性质、数额、退还条件主要看合同约定。 租房场景里，押金通常用来担保租金支付和房屋完好。租期届满、承租人按约定状态返还房屋后，押金应当按约定退还。 房东如果说房屋损坏要扣押金，应当说明损坏情况、维修费用和依据。双方协商不成，可以保留照片、聊天记录、维修单据等证据。 签约时写清楚：押金多少、什么情况下扣、扣多少、什么时候退。比事后争论有用得多。",
  "contract-deposit": "定金是债权的担保。定金合同自实际交付定金时成立，数额由当事人约定，但不得超过主合同标的额的一定比例。 规则可以记成两句话：付定金的一方违约，定金不退；收定金的一方违约，双倍返还。 如果合同里同时约定了违约金和定金，一方违约时，对方只能选择其中一种，不能两个都要。",
  "contract-ecommerce": "电子数据交换、电子邮件等可以有形表现内容、随时调取查用的数据电文，可以视为书面形式。 在电商场景里，商品信息符合要约条件、用户提交订单成功的，合同成立，除非当事人另有约定。 交付商品并采用快递物流方式的，收货人签收时间一般为交付时间。 七天无理由退货规则主要规定在《消费者权益保护法》中，本库尚未收录该法。遇到具体退货问题，先看平台规则和商品性质，必要时查阅该法原文。",
  "contract-form": "合同可以采用书面形式、口头形式或者其他形式。 书面形式不只是纸质合同。合同书、信件、电报、传真，以及微信、电子邮件等可以有形表现内容、随时调取查用的数据电文，都可能被视为书面形式。 口头约定虽然可能成立，但发生争议时举证更难。重要的交易，留下书面记录更稳妥。",
  "contract-format-clause": "格式条款是一方为了重复使用而预先拟定，并在订立合同时未与对方协商的条款。 提供格式条款的一方应当遵循公平原则确定当事人之间的权利和义务，并采取合理方式提示对方注意免除或者减轻其责任等与对方有重大利害关系的条款。 不合理地免除或者减轻自己责任、加重对方责任、限制对方主要权利的格式条款，可能被认定无效。 相关概念： 合同成立 。",
  "contract-formation": "合同是民事主体之间设立、变更、终止民事法律关系的协议。双方就主要条款达成一致，合同通常就成立了。 成立解决的是「有没有这个合同」，生效解决的是「这个合同能不能产生法律效力」。两者不是一回事。 形式问题可以继续看 合同的形式 。",
  "contract-fraud": "一方以欺诈手段，使对方在违背真实意思的情况下实施的民事法律行为，受欺诈方有权请求人民法院或者仲裁机构予以撤销。 撤销权有行使期限。当事人自知道或者应当知道撤销事由之日起一年内、重大误解的当事人自知道或者应当知道撤销事由之日起九十日内没有行使撤销权，撤销权消灭。 受胁迫的当事人自胁迫行为终止之日起一年内没有行使撤销权的，撤销权消灭。 相关概念： 合同成立 。",
  "contract-gift": "赠与合同是赠与人将自己的财产无偿给予受赠人，受赠人表示接受赠与的合同。 赠与人在赠与财产的权利转移之前可以撤销赠与。经过公证的赠与合同，或者依法不得撤销的具有救灾、扶贫、助残等公益、道德义务性质的赠与合同，不适用任意撤销。 受赠人严重侵害赠与人或者赠与人近亲属的合法权益等情形，赠与人还可以依法撤销赠与。 相关概念： 合同成立 。",
  "contract-guarantee": "保证合同是为保障债权实现，保证人和债权人约定，当债务人不履行到期债务或者发生当事人约定的情形时，保证人履行债务或者承担责任的合同。 保证方式包括一般保证和连带责任保证。对保证方式没有约定或者约定不明确的，按照一般保证承担保证责任。 一般保证的保证人在主合同纠纷未经审判或者仲裁，并就债务人财产依法强制执行仍不能履行债务前，有权拒绝向债权人承担保证责任，法律另有规定的除外。 相关概念： 借款合同 。",
  "contract-lease": "租赁合同是出租人把租赁物交给承租人使用、收益，承租人支付租金的合同。 租期六个月以上的，应当采用书面形式。没写书面合同、又无法确定租期的，视为不定期租赁，双方都可以随时解除，但出租人解除应当在合理期限之前通知。 租期届满，承租人应当返还租赁物，返还时符合按照约定或者租赁物性质使用后的状态即可。 租期届满继续使用、出租人没有提出异议的，原合同继续有效，但变成不定期租赁。 押金怎么处理，见 押金 。",
  "contract-limitation": "向人民法院请求保护民事权利的诉讼时效期间一般为三年，法律另有规定的除外。 时效从权利人知道或者应当知道权利受到损害以及义务人之日起计算。 催款、对方承诺还款、提起诉讼等行为可能引起诉讼时效中断。保留催款聊天记录、转账凭证、书面承诺，比单纯记着「他欠我钱」有用。",
  "contract-loan": "借款合同是借款人向贷款人借款，到期返还借款并支付利息的合同。 自然人之间的借款合同，自贷款人实际提供借款时成立。所以转账记录、交付凭证很重要。 利息方面：没有约定利息的，视为没有利息；禁止高利放贷，利率不得违反国家有关规定。 借钱不还，要注意 诉讼时效 。",
  "contract-offer": "订立合同通常经过「要约」和「承诺」两步：一方提出具体条件，另一方表示同意。 要约的内容需要具体确定，并表明对方一旦同意，提出方就受约束。普通的价目表、广告，很多时候只是邀请别人来谈，还不算要约。 电子交易里，商品信息是否符合要约条件，会直接影响合同什么时候成立，可以继续看 电子合同与网购 。",
  "contract-penalty": "双方可以约定，一方违约时支付一定数额的违约金，也可以约定损失赔偿额的计算方法。 违约金不是写多少就一定要付多少。过分高于实际损失的，可以请求适当减少；低于实际损失的，也可以请求增加。 同时约定违约金和定金的，只能择一适用，见 定金罚则 。",
  "contract-performance": "合同生效后，双方要按照约定全面履行自己的义务。 除了写明的条款，诚信原则还会带来通知、协助、保密等附随义务。很多事情合同没写细，也不代表可以不管。 不履行或者履行不符合约定，就可能进入 违约责任 。",
  "contract-sale": "买卖合同是出卖人转移标的物的所有权于买受人，买受人支付价款的合同。 出卖人应当履行向买受人交付标的物或者交付提取标的物的单证，并转移标的物所有权的义务。 标的物质量不符合约定的，买受人可以依照约定或者法律规定要求出卖人承担违约责任。 相关概念： 违约责任 。",
  "contract-termination": "合同可以协商解除，也可以在达到法定或约定条件时解除。 常见的法定情形包括：不可抗力致使不能实现合同目的、一方明确表示不履行主要债务、迟延履行主要债务经催告后仍不履行、根本违约等。 解除合同后，已经发生的违约责任并不当然消失，仍然可以主张赔偿。",
  "labor-arbitration-limitation": "劳动争议申请仲裁的时效期间为一年，从当事人知道或者应当知道其权利被侵害之日起计算。 劳动关系存续期间因拖欠劳动报酬发生争议的，不受一年时效限制；但劳动关系终止的，应当自劳动关系终止之日起一年内提出。 时效可能因主张权利、对方同意履行等情形中断。保留催讨工资、要求补缴社保、协商记录的聊天记录和书面材料。",
  "labor-arbitration": "发生劳动争议，当事人可以协商，也可以请调解组织调解；调解不成，可以申请劳动仲裁。 对仲裁裁决不服的，除法律另有规定外，可以向人民法院提起诉讼。 时效问题见 仲裁时效 。",
  "labor-burden-of-proof": "发生劳动争议，当事人对自己提出的主张，有责任提供证据。 与争议事项有关的证据属于用人单位掌握管理的，用人单位应当提供；用人单位不提供的，应当承担不利后果。 劳动者先证明基础事实：劳动关系、工资标准、加班事实的初步线索。考勤表、工资表等由单位掌握的材料，可以要求单位提供。",
  "labor-consensual-termination": "用人单位与劳动者协商一致，可以解除劳动合同。 用人单位向劳动者提出解除劳动合同并与劳动者协商一致解除的，应当支付经济补偿。 签离职协议前，确认补偿金额、支付日期、社保和公积金处理、竞业限制、保密义务。不要在空白协议或不看清条款的情况下签字。",
  "labor-dispatch": "经营劳务派遣业务应当具备法定条件，并依法办理行政许可。 劳务派遣单位是本法所称用人单位，应当履行用人单位对劳动者的义务。 劳动合同用工是我国的企业基本用工形式。劳务派遣用工是补充形式，只能在临时性、辅助性或者替代性的工作岗位上实施。 相关概念： 书面劳动合同 。",
  "labor-double-wage": "用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。 双倍工资的主张受仲裁时效限制。发现公司长期不签合同，尽早保留工资流水、考勤记录、工作沟通记录，并咨询当地劳动仲裁机构。",
  "labor-illegal-dismissal": "用人单位违反法律规定解除或者终止劳动合同的，应当依照经济补偿标准的二倍向劳动者支付赔偿金。 经济补偿按工作年限计算，每满一年一个月工资。 违法解除赔偿金与经济补偿一般不能同时主张。先判断公司属于合法解除、协商解除还是违法解除，再决定主张哪一项。",
  "labor-noncompete": "用人单位与劳动者可以在劳动合同中约定保守用人单位的商业秘密和与知识产权相关的保密事项。 对负有保密义务的劳动者，用人单位可以在劳动合同或者保密协议中与劳动者约定竞业限制条款，并约定在解除或者终止劳动合同后，在竞业限制期限内按月给予劳动者经济补偿。 竞业限制的人员限于用人单位的高级管理人员、高级技术人员和其他负有保密义务的人员。 相关概念： 辞职与被迫解除 。",
  "labor-open-ended": "无固定期限劳动合同，是指用人单位与劳动者约定无确定终止时间的劳动合同。 连续订立二次固定期限劳动合同，且劳动者没有法定情形，续订劳动合同时，除劳动者提出订立固定期限劳动合同外，应当订立无固定期限劳动合同。 无固定期限劳动合同不是「铁饭碗」，在法定情形下仍然可以解除。 相关概念： 书面劳动合同 。",
  "labor-overtime-pay": "有下列情形之一的，用人单位应当按照高于正常工作时间工资的标准支付工资报酬： - 安排延长工作时间的，支付不低于工资的 150%； - 休息日安排工作又不能安排补休的，支付不低于工资的 200%； - 法定休假日安排工作的，支付不低于工资的 300%。 主张加班费，考勤记录、排班表、工作群通知、加班审批记录最关键。平时注意保存，离职后再找往往很难。",
  "labor-probation": "试用期长短和合同期限挂钩：三个月以上不满一年的，试用期不得超过一个月；一年以上不满三年的，不得超过二个月；三年以上固定期限和无固定期限的，不得超过六个月。 同一用人单位与同一劳动者只能约定一次试用期，试用期包含在劳动合同期限内。 试用期内，除劳动者有法定情形外，用人单位不得随意解除劳动合同。 被辞退怎么办，见 违法解除赔偿金 。",
  "labor-protected-period": "女职工在孕期、产期、哺乳期的，用人单位不得依照本法关于无过失性辞退和经济性裁员的规定解除劳动合同。 劳动合同期满，有本法规定的三期等情形之一的，劳动合同应当续延至相应的情形消失时终止。 三期保护不是绝对不能被辞退。劳动者存在严重违反规章制度等法定情形的，用人单位仍可能依法解除。 相关概念： 违法解除赔偿金 。",
  "labor-resignation": "劳动者提前三十日以书面形式通知用人单位，可以解除劳动合同。劳动者在试用期内提前三日通知用人单位，可以解除劳动合同。 用人单位未按照劳动合同约定提供劳动保护或者劳动条件、未及时足额支付劳动报酬、未依法为劳动者缴纳社会保险费等情形下，劳动者可以解除劳动合同。 劳动者依照被迫解除的规定解除劳动合同的，用人单位应当支付经济补偿。 相关概念： 经济补偿 。",
  "labor-severance": "有下列情形之一的，用人单位应当向劳动者支付经济补偿，例如：劳动者因用人单位未按约定提供劳动保护、未及时足额支付劳动报酬等解除劳动合同；用人单位提出并与劳动者协商一致解除；用人单位依法裁减人员等。 经济补偿按工作年限计算：每满一年支付一个月工资；六个月以上不满一年的，按一年计算；不满六个月的，支付半个月工资。 违法解除的赔偿金是经济补偿标准的二倍，见 违法解除赔偿金 。",
  "labor-social-insurance": "用人单位应当自用工之日起三十日内为其职工向社会保险经办机构申请办理社会保险登记。 用人单位应当自行申报、按时足额缴纳社会保险费，非因不可抗力等法定事由不得缓缴、减免。 「自愿放弃社保」的协议不能当然免除单位的缴费义务。发现单位长期不缴、少缴，可以向社保经办机构或劳动保障监察部门反映。",
  "labor-work-hours": "用人单位由于生产经营需要，经与工会和劳动者协商后可以延长工作时间，一般每日不得超过一小时。 因特殊原因需要延长的，在保障劳动者身体健康的条件下，每日不得超过三小时，每月不得超过三十六小时。 加班了怎么算钱，见 加班工资 。",
  "labor-work-injury": "职工应当参加工伤保险，由用人单位缴纳工伤保险费，职工个人不缴纳。 职工因工作原因受到事故伤害或者患职业病，且经工伤认定的，享受工伤保险待遇；其中经劳动能力鉴定丧失劳动能力的，享受伤残待遇。 工伤认定有申请期限和材料要求，具体程序主要规定在《工伤保险条例》，本库暂未收录。受伤后尽快就医、保留病历和事故证明，并及时向单位或社保部门咨询申请流程。",
  "labor-written-contract": "建立劳动关系，应当订立书面劳动合同。 已建立劳动关系、未同时订立书面劳动合同的，应当自用工之日起一个月内订立。 公司超过一个月还不签，可能涉及双倍工资，见 双倍工资 。",
  "marriage-adoption": "收养人应当同时具备无子女或者只有一名子女、有抚养教育被收养人的能力、未患有医学上认为不应当收养子女的疾病、无不利于被收养人健康成长的违法犯罪记录等条件。 收养应当向县级以上人民政府民政部门登记，收养关系自登记之日起成立。 收养关系成立后，养父母与养子女间的权利义务关系，适用父母子女关系的规定。 相关概念： 继承基础 。",
  "marriage-betrothal-gift-rule": "法律禁止包办、买卖婚姻和其他干涉婚姻自由的行为，禁止借婚姻索取财物。 彩礼返还的具体规则由最高人民法院相关司法解释规定，本库暂未收录。实践中通常会考虑：是否办理结婚登记、是否共同生活、共同生活时间长短、彩礼数额、彩礼用途、双方过错等。具体案件建议查阅现行司法解释或咨询律师。",
  "marriage-child-support": "离婚后，子女由一方直接抚养的，另一方应当负担部分或者全部抚养费。 负担费用的多少和期限的长短，由双方协议；协议不成的，由人民法院判决。抚养费一般包括生活费、教育费、医疗费等合理支出。",
  "marriage-cohabitation": "无效的或者被撤销的婚姻自始没有法律约束力，当事人不具有夫妻的权利和义务。 同居期间所得的财产，由当事人协议处理；协议不成的，由人民法院根据照顾无过错方的原则判决。 对重婚导致的无效婚姻的财产处理，不得侵害合法婚姻当事人的财产权益。 相关概念： 夫妻共同财产 。",
  "marriage-common-debt": "夫妻双方共同签名或者一方事后追认等共同意思表示所负的债务，以及一方在婚姻关系存续期间以个人名义为家庭日常生活需要所负的债务，属于夫妻共同债务。 一方以个人名义超出家庭日常生活需要所负的债务，不属于共同债务，但债权人能够证明该债务用于夫妻共同生活、共同生产经营或者基于双方共同意思表示的除外。 离婚时，夫妻共同债务应当共同偿还。",
  "marriage-community-property": "婚姻关系存续期间所得的下列财产，一般属于夫妻共同财产：工资、奖金、劳务报酬；生产、经营、投资的收益；知识产权的收益；继承或者受赠的财产（遗嘱或者赠与合同确定只归一方的除外）等。 哪些属于个人财产，见 个人财产 ；双方也可以书面约定财产归属，见 婚前财产约定 。",
  "marriage-cooling-off": "自婚姻登记机关收到离婚登记申请之日起三十日内，任何一方不愿意离婚的，可以向婚姻登记机关撤回离婚登记申请。 冷静期届满后三十日内，双方应当亲自到婚姻登记机关申请发给离婚证；未申请的，视为撤回离婚登记申请。 冷静期只适用于协议离婚。诉讼离婚不适用这一程序。",
  "marriage-custody-rule": "父母与子女间的关系，不因父母离婚而消除。离婚后，子女无论由父或者母直接抚养，仍是父母双方的子女。 不满两周岁的子女，以由母亲直接抚养为原则；已满两周岁的，父母双方协议不成时，由法院按照最有利于未成年子女的原则判决；已满八周岁的，应当尊重其真实意愿。 抚养费怎么负担，见 抚养费 。",
  "marriage-divorce-methods": "离婚有两种常见方式：协议离婚和诉讼离婚。 协议离婚要求双方自愿，签订书面离婚协议，并亲自到婚姻登记机关申请离婚登记。 一方要求离婚的，可以由有关组织调解或者直接向法院提起离婚诉讼。 协议离婚还要经过冷静期，见 离婚冷静期 。",
  "marriage-domestic-violence": "家庭暴力不只是打人。以殴打、捆绑、残害、限制人身自由以及经常性谩骂、恐吓等方式实施的身体、精神等侵害行为，都可能构成家庭暴力。 因家庭暴力导致离婚，调解无效的，法院应当准予离婚。 保护自己的方式，见 人身安全保护令 。",
  "marriage-elderly-support": "父母对未成年子女负有抚养、教育和保护的义务；成年子女对父母负有赡养、扶助和保护的义务。 父母不履行抚养义务的，未成年子女或者不能独立生活的成年子女，有要求父母给付抚养费的权利。 成年子女不履行赡养义务的，缺乏劳动能力或者生活困难的父母，有要求成年子女给付赡养费的权利。 相关概念： marriage-child-support 。",
  "marriage-fault-damages": "有下列情形之一，导致离婚的，无过错方有权请求损害赔偿：重婚；与他人同居；实施家庭暴力；虐待、遗弃家庭成员；有其他重大过错。 夫妻应当互相忠实、互相尊重。但「出轨」是一个生活用语，不一定等同于法律上的「与他人同居」。主张损害赔偿，需要证明达到法定情形。",
  "marriage-hidden-assets": "夫妻一方隐藏、转移、变卖、毁损、挥霍夫妻共同财产，或者伪造夫妻共同债务企图侵占另一方财产的，在离婚分割夫妻共同财产时，对该方可以少分或者不分。 离婚后，另一方发现有上述行为的，可以向人民法院提起诉讼，请求再次分割夫妻共同财产。 婚姻关系存续期间，一方有隐藏、转移、变卖、毁损、挥霍夫妻共同财产或者伪造夫妻共同债务等严重损害夫妻共同财产利益行为的，另一方可以向人民法院请求分割共同财产。 相关概念： 夫妻共同财产 。",
  "marriage-inheritance": "遗产按照下列顺序继承：第一顺序为配偶、子女、父母；第二顺序为兄弟姐妹、祖父母、外祖父母。 继承开始后，由第一顺序继承人继承，第二顺序继承人不继承；没有第一顺序继承人继承的，才由第二顺序继承人继承。 这里的子女包括婚生子女、非婚生子女、养子女和有扶养关系的继子女。",
  "marriage-personal-property": "下列财产一般属于夫妻一方的个人财产：一方的婚前财产；一方因受到人身损害获得的赔偿或者补偿；遗嘱或者赠与合同中确定只归一方的财产；一方专用的生活用品等。 婚前财产不会因为结婚自动变成共同财产。但婚后用共同财产还贷、财产增值怎么处理，往往需要结合具体证据和司法解释判断。",
  "marriage-prenup": "男女双方可以约定婚姻关系存续期间所得的财产以及婚前财产归各自所有、共同所有，或者部分各自所有、部分共同所有。 约定应当采用书面形式。没有约定或者约定不明确的，适用法定的共同财产和个人财产规则。",
  "marriage-protection-order": "当事人因遭受家庭暴力或者面临家庭暴力的现实危险，可以向人民法院申请人身安全保护令。 保护令可以包括：禁止被申请人实施家庭暴力；禁止骚扰、跟踪、接触申请人及其相关近亲属；责令被申请人迁出申请人住所等措施。 情况紧急时，先报警、就医、联系妇联或居委会，保留报警记录、验伤材料、聊天记录。申请人身安全保护令可以书面申请，书面确有困难也可以口头申请。",
  "marriage-stepchild": "继父母与继子女间，不得虐待或者歧视。 继父或者继母和受其抚养教育的继子女间的权利义务关系，适用父母子女关系的规定。 法定继承中的子女，包括婚生子女、非婚生子女、养子女和有扶养关系的继子女。 相关概念： 继承基础 。"
};
